}

Method.Source:
    /// <summary>
    /// Creates a <c>METSalesInvoicePostedBusinessEventContract</c>.
    /// </summary>
    /// <param name = "_dataAreaId">Company Id</param>
    /// <returns>A <c>METSalesInvoicePostedBusinessEventContract</c>.</returns>
    public static METSalesInvoicePostedBusinessEventContract newFromDataAreaId(DataAreaId _dataAreaId)
    {
        var contract = new METSalesInvoicePostedBusinessEventContract();
        contract.initialize(_dataAreaId);

        return contract;
    }

/// <summary>
/// Initialize the data contract
/// </summary>
/// <param name = "_dataAreaId">dataAreaId</param>
private void initialize(DataAreaId _dataAreaId)
{
    dataAreaId = _dataAreaId;
}

    /// <summary>
    /// Gets/sets the company ID
    /// </summary>
    /// <param name = "_dataAreaId">company ID</param>
    /// <returns>returns the company ID</returns>
    [DataMember('LegalEntity'), BusinessEventsDataMember("@AccountsReceivable:LegalEntity")]
    public DataAreaId parmDataAreaId(LegalEntityDataAreaId _dataAreaId = dataAreaId)
    {
        dataAreaId = _dataAreaId;

        return dataAreaId;
    }
